function hint(action,text){return `<span class="hint">${key(action)}${text}</span>`}function prompts(){for(const e of $$('[data-prompt]'))e.innerHTML=key(e.dataset.prompt);const modal=panels.length>0;$('#footer').innerHTML=`<div class="hints">${hint('a','Seleziona')}${hint('b','Indietro')}${!modal&&page==='home'&&lower>=0?hint('lb','')+hint('rb','Cambia sezione'):''}${!modal&&(detailGame||page==='explore')?hint('lb','')+hint('rb','Cambia scheda'):''}</div><span class="footer-status">${mode==='Keyboard'?'Mouse e tastiera':mode} <span style="margin:0 12px">·</span> <span class="nova-wordmark"><img src="assets/nova-wordmark.png" alt="Nova Launcher" draggable="false"></span></span>`;}
