let backgroundRequest=0;
function clearBackground(){for(const scene of $$('.scene')){scene.style.backgroundImage='none';scene.classList.remove('visible')}document.body.classList.add('neutral-scene');}
function setBackground(src){src=String(src||'');if(src===background)return;const request=++backgroundRequest;background=src;clearBackground();if(!src)return;const image=new Image();image.onload=()=>{if(request!==backgroundRequest||background!==src)return;const scenes=$$('.scene');layer=1-layer;scenes[layer].style.backgroundImage='url('+JSON.stringify(src)+')';scenes[layer].classList.add('visible');document.body.classList.remove('neutral-scene')};image.onerror=()=>{if(request===backgroundRequest){background='';clearBackground()}};image.src=src;}
