function sources(g){return `<span class="sources">${[...new Set((g.sources||[g.source]).map(n=>n==='Steam Family Sharing'?'Steam':n==='Ubisoft Connect'?'Ubisoft':n==='Microsoft Store'?'Xbox':n))].map(n=>['Steam','Hydra','Epic','Xbox','GOG','Amazon','Ubisoft'].includes(n)?`<img src="assets/${n}.png" alt="${esc(n)}" title="${esc(n)}">`:`<span>${esc(n)}</span>`).join('')}</span>`;}
