function button(text,action,ic='',cls=''){return `<button class="action ${cls}" data-action="${action}">${ic?icon(ic):''}${text}</button>`}function row(text,action,ic='',sub='',extra=''){return `<button class="row-action" data-action="${action}" ${extra}>${ic?icon(ic):''}<span class="row-copy"><strong class="row-title">${text}</strong>${sub?`<small>${sub}</small>`:''}</span></button>`;}
