function render(keepScroll=false){document.documentElement.style.setProperty('--accent',state.settings.accent||'#c4a4ff');const savedFocus=captureFocus();generation++;const scroll=$('#main').scrollTop,railScroll=$('#recent-rail')?.scrollLeft||0,shopScrolls=new Map($$('[data-shop-rail]').map(el=>[el.dataset.shopRail,el.scrollLeft]));document.body.dataset.page=detailGame||(typeof shopGame!=='undefined'&&shopGame)?'details':page;document.body.classList.toggle('lower',lower>=0&&page==='home'&&!detailGame);document.body.classList.toggle('reduce-motion',!!state.settings.reduceMotion);for(const n of $$('nav button'))n.classList.toggle('active',n.dataset.page===page);$('#main').innerHTML=detailGame?detailMarkup(detailGame):page==='home'?lower>=0?lowerMarkup():renderHome():page==='library'?libraryMarkup():page==='explore'?exploreMarkup():settingsMarkup();$('#main').scrollTop=keepScroll?scroll:0;if(keepScroll&&$('#recent-rail'))$('#recent-rail').scrollLeft=railScroll;if(keepScroll)for(const rail of $$('[data-shop-rail]'))rail.scrollLeft=shopScrolls.get(rail.dataset.shopRail)||0;prompts();syncBackground();if(typeof updateDetailContrast==='function')updateDetailContrast();updateFriendsHeader();restoreFocus(savedFocus);if(page==='home'&&lower<0&&!detailGame)scheduleHomeActivity(selected);}
