let previousButtons=[],lastDirection='',repeatAt=0,armed=false,wasFocused=false;function pollPad(time){const pad=[...(navigator.getGamepads?.()||[])].find(Boolean),focused=document.hasFocus();if(!pad||!focused){armed=false;previousButtons=[];wasFocused=focused;requestAnimationFrame(pollPad);return;}const pressed=pad.buttons.map(b=>b.pressed),neutral=!pressed.some(Boolean)&&pad.axes.slice(0,2).every(v=>Math.abs(v)<.35);if(!armed){if(neutral)armed=true;previousButtons=pressed;requestAnimationFrame(pollPad);return;}const edge=i=>pressed[i]&&!previousButtons[i];const horizontal=pad.axes[0]||0,vertical=pad.axes[1]||0;const dir=pressed[12]||vertical<-.6?'up':pressed[13]||vertical>.6?'down':pressed[14]||horizontal<-.6?'left':pressed[15]||horizontal>.6?'right':'';if(dir||pressed.some(Boolean)){setMode(/Sony|DualSense|DualShock|PlayStation|054c/i.test(pad.id)?'PlayStation':'Xbox');}if(edge(0))confirm();if(edge(1))back();if(!detailGame){if(edge(6))changeMain(-1);if(edge(7))changeMain(1);}if(edge(4))changeSection(-1);if(edge(5))changeSection(1);if(edge(9)&&!panels.length)showOptions();if(dir&&(dir!==lastDirection||time>=repeatAt)){move(dir);repeatAt=time+(dir!==lastDirection?340:140);}lastDirection=dir;previousButtons=pressed;wasFocused=focused;requestAnimationFrame(pollPad);}window.addEventListener('blur',()=>{armed=false;document.body.classList.remove('pad-mode')});requestAnimationFrame(pollPad);
