// Focus is owned by the launcher, independently of Chromium input heuristics.
function focusScope(){return panels.length?$('#panel'):document;}
function focusScopeKey(){return panels.length?'panel:'+panels.at(-1).title:page+':'+lower+':'+(detailGame?.id||'');}
function validFocus(el){return !!el&&el.matches?.('button,input,select,summary[data-offer-conditions],[data-achievement],[data-friend],[data-feed-item],[data-info-block],[data-reader]')&&!el.disabled&&!!el.getClientRects().length&&focusScope().contains(el);}
function paintFocus(){for(const el of $$('.controller-focus'))el.classList.remove('controller-focus');const el=document.activeElement;if(validFocus(el))el.classList.add('controller-focus');}
function captureFocus(){const el=document.activeElement;if(!validFocus(el))return null;return {scope:focusScopeKey(),id:el.id,attrs:[...el.attributes].filter(a=>a.name.startsWith('data-')&&!(el.hasAttribute('data-shop-id')&&a.name==='data-shop-game')).map(a=>[a.name,a.value]),aria:el.getAttribute('aria-label'),tag:el.tagName};}
function restoreFocus(saved){if(saved&&saved.scope===focusScopeKey()){const scope=focusScope();let found=saved.id?document.getElementById(saved.id):null;if(!found&&saved.attrs.length)found=focusables(scope).find(el=>el.tagName===saved.tag&&saved.attrs.every(([k,v])=>el.getAttribute(k)===v));if(!found&&saved.aria)found=focusables(scope).find(el=>el.getAttribute('aria-label')===saved.aria);if(found&&validFocus(found)){found.focus({preventScroll:true});if(found.matches('[data-shop-id]'))found.scrollIntoView({block:'nearest',inline:'nearest',behavior:'instant'});paintFocus();return true;}}if(validFocus(document.activeElement)){paintFocus();return true;}return false;}
let focusRepairQueued=false;
function repairFocus(){if(focusRepairQueued)return;focusRepairQueued=true;requestAnimationFrame(()=>{focusRepairQueued=false;if(!document.hasFocus()||!state.games.length)return;if(!validFocus(document.activeElement))focusFirst();paintFocus();});}
document.addEventListener('focusin',paintFocus);
document.addEventListener('focusout',repairFocus);
window.addEventListener('focus',repairFocus);
new MutationObserver(repairFocus).observe($('#main'),{childList:true,subtree:true});
new MutationObserver(repairFocus).observe($('#panel'),{childList:true,subtree:true});
paintFocus();

