const runningGames=new Set();setInterval(async()=>{if(state.settings.novaAccount?.required&&!state.settings.novaAccount.connected)return;try{const ids=await window.nova.call('running');runningGames.clear();ids.forEach(id=>runningGames.add(id));for(const b of $$('[data-action="play"]')){const g=detailGame||selected;if(!g)continue;const copy=activeCopy(g);const text=runningGames.has(g.id)?'Chiudi':copy?.installed?'Gioca':'Installa';if(b.dataset.launchLabel!==text){b.dataset.launchLabel=text;b.innerHTML=icon(runningGames.has(g.id)?'power':copy?.installed?'play':'download')+text;}}}catch{}},3000);

// Achievement rows form a linear reading list inside the game page.
let achievementReturnFilter='all';
function focusAchievementTarget(target){if(!target)return;target.focus({preventScroll:true});target.scrollIntoView({block:'nearest',inline:'nearest',behavior:state.settings.reduceMotion?'instant':'smooth'});paintFocus();}
function navigateAchievements(current,direction){
 if(panels.length||!detailGame||!current)return false;
 const rows=$$('#ach-list [data-achievement]');
 if(current.matches('[data-ach-filter]')&&direction==='down'){
  if(rows.length){achievementReturnFilter=current.dataset.achFilter;focusAchievementTarget(rows[0]);}return true;
 }
 if(current.matches('.ach-sources button')&&direction==='down'){focusAchievementTarget($('.ach-filters button.active')||$('.ach-filters button'));return true;}
 const index=rows.indexOf(current);if(index<0)return false;
 if(direction==='up')focusAchievementTarget(index?rows[index-1]:$('.ach-filters [data-ach-filter="'+achievementReturnFilter+'"]')||$('.ach-filters button.active'));
 else if(direction==='down')focusAchievementTarget(rows[Math.min(index+1,rows.length-1)]);
 return true;
}

// Shared social panel: one entry point in the system bar, available on every page.
function friendOnline(f){return [0,3,4,6].includes(f.status);}
function friendStatus(f){return ({0:'Online',3:'Assente',4:'Non disturbare',6:'In diretta'})[f.status]||'Offline';}
function updateFriendsHeader(){const button=$('#friends-toggle'),symbol=$('#friends-symbol'),badge=$('#friends-count');if(!button)return;if(symbol&&!symbol.innerHTML)symbol.innerHTML=icon('users');const known=state.discord.status==='ready'&&!state.discord.stale,count=online().length;if(badge){badge.hidden=!known;badge.textContent=String(count);badge.classList.toggle('has-online',count>0);}button.setAttribute('aria-label',known?'Amici · '+count+' online':'Amici · presenze non disponibili');button.title=known?'Amici · '+count+' online':'Amici';}
function friendAccounts(f){return f.accounts?.length?f.accounts:[f];}
function friendPlatforms(f){return [...new Set(friendAccounts(f).flatMap(a=>String(a.store||'Discord').split(/\s*\+\s*/)).filter(Boolean))];}
function friendPlatformIcons(f){const assets={'Steam':'Steam','Discord':'Discord','Epic':'Epic','Epic Games':'Epic','GOG':'GOG','Hydra':'Hydra','Xbox':'Xbox','Ubisoft':'Ubisoft'};return '<span class="friend-platforms" aria-label="Piattaforme">'+friendPlatforms(f).map(name=>assets[name]?'<img class="friend-platform-logo" src="assets/icons/'+assets[name]+'.png" alt="'+esc(name)+'" title="'+esc(name)+'">':'<span class="friend-platform-unknown" title="'+esc(name)+'" aria-label="'+esc(name)+'">'+icon('users')+'</span>').join('')+'</span>';}
function friendInDiscordVoice(f){return friendAccounts(f).some(a=>(a.store||'Discord')==='Discord'&&friendOnline(a)&&a.voiceKnown===true&&a.voiceInChannel===true);}
function friendPresenceMarkup(f){const active=friendOnline(f),voice=active&&friendInDiscordVoice(f),game=active?String(f.game||'').trim():'';return '<p class="friend-presence"><i class="presence-dot '+(active?f.status===3?'away':f.status===4?'busy':'online':'offline')+'" aria-hidden="true"></i><span class="friend-status-label">'+esc(friendStatus(f))+'</span>'+(voice?'<span class="friend-voice" role="img" aria-label="In un canale vocale Discord" title="In un canale vocale Discord">'+icon('audio')+'</span>':'')+(game?'<span class="friend-presence-separator" aria-hidden="true">·</span><span class="friend-playing">'+esc(game)+'</span>':'')+'</p>';}
function friendRows(people){return people.map(f=>'<div class="friend-row" role="listitem" tabindex="0" data-friend="'+esc((f.store||'Discord')+':'+f.id)+'">'+(f.avatar?'<img class="friend-avatar" src="'+esc(f.avatar)+'" alt="">':icon('users'))+'<div class="friend-copy"><h3 class="friend-name"><span>'+esc(f.name)+'</span>'+friendPlatformIcons(f)+'</h3>'+friendPresenceMarkup(f)+'</div></div>').join('');}
function friendsPanelMarkup(){if(state.discord.stale||state.discord.status!=='ready')return '<div class="empty"><h3>Presenze non disponibili</h3><p>Collega Discord o Steam da Impostazioni → Account e librerie.</p></div>';const people=[...socialPeople()].sort((a,b)=>Number(!!b.game&&friendOnline(b))-Number(!!a.game&&friendOnline(a))||String(a.name).localeCompare(String(b.name),'it')),connected=people.filter(friendOnline),offline=people.filter(f=>!friendOnline(f));return '<div class="social-summary"><strong>'+connected.length+'</strong><span>amici online</span></div><div class="social-list" role="list" aria-label="Amici online">'+friendRows(connected)+'</div>'+(!connected.length?'<p class="note">Nessun amico online in questo momento.</p>':'')+(offline.length?'<h3 class="offline-heading">Offline · '+offline.length+'</h3><div class="social-list" role="list" aria-label="Amici offline">'+friendRows(offline)+'</div>':'');}
function adoptFriends(data){state.discord=data;updateFriendsHeader();const panel=panels.at(-1);if(panel?.kind!=='friends')return;const content=$('#social-content');if(!content)return;const markup=friendsPanelMarkup();if(content.innerHTML===markup)return;const focus=captureFocus(),body=$('#panel .panel-body'),scroll=body.scrollTop;content.innerHTML=markup;body.scrollTop=scroll;if(!restoreFocus(focus))focusFirst();}
function showFriends(){openPanel('Amici',()=>'<div id="social-content">'+friendsPanelMarkup()+'</div>');panels.at(-1).kind='friends';call('friends').then(adoptFriends).catch(()=>{});}
// Personal activity belongs to the highlighted game, not the social presence area.
function recentUnlocks(g){return [...(g?.achievements||[])].filter(a=>a.unlocked).sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)).slice(0,2);}
function activityMarkup(g){const items=recentUnlocks(g);return '<button class="hero-activity" data-action="activity" aria-label="La tua attività in '+esc(g.title)+'"><span class="activity-heading">La tua attività</span><span class="activity-time">'+icon('clock')+'<span>'+hours(g.playtime)+'</span><small>giocate</small></span><span class="activity-label">Ultimi obiettivi sbloccati</span>'+(items.length?items.map(a=>'<span class="activity-achievement">'+(a.icon?'<img src="'+esc(a.icon)+'" alt="">':icon('trophy'))+'<span><strong>'+esc(a.name)+'</strong><small>'+esc(a.date?date(a.date):'Sbloccato')+'</small></span></span>').join(''):'<span class="activity-empty">'+(activityLoadingId===g.id?'Controllo i tuoi obiettivi…':'Nessuno sblocco disponibile')+'</span>')+'</button>';}
let activityTimer,activityBusy=false,activityLoadingId='',activityUpdated=new Map();
function refreshActivityCard(id){if(selected?.id!==id||page!=='home'||lower>=0||detailGame)return;const current=$('.hero-meta');if(current)current.innerHTML=meta(selected);}
function scheduleHomeActivity(g){clearTimeout(activityTimer);if(!g||detailGame||page!=='home'||lower>=0)return;if(Date.now()-(activityUpdated.get(g.id)||0)<60000)return;activityTimer=setTimeout(async()=>{if(activityBusy)return;activityBusy=true;const id=g.id;activityLoadingId=id;refreshActivityCard(id);try{const data=await call('activity',{id});const existing=game(id);if(existing)Object.assign(existing,data);if(selected?.id===id)selected=existing||selected;activityUpdated.set(id,Date.now());}catch{}finally{activityBusy=false;activityLoadingId='';refreshActivityCard(id);if(selected?.id!==id)scheduleHomeActivity(selected);}},550);}


function changeSection(delta){if(state.settings.novaAccount?.required&&!state.settings.novaAccount.connected)return;if(typeof galleryStep==='function'&&galleryStep(delta))return;window.novaSounds?.play("navigate");if(panels.length)return;if(page==='explore'&&!detailGame){if(shopGame){changeShopTab(delta);}else{exploreTab=(exploreTab+delta+3)%3;render();$('.shop-tabs button.active')?.focus({preventScroll:true});paintFocus();ensureShopCalendar();}return;}if(detailGame){changeGameTab(delta);return;}if(page==='home'&&lower>=0)changeLower((lower+delta+lowerNames.length)%lowerNames.length);}
